const STATE_MACHINE_JS = resolve(SKILL_BUNDLE_PATH, 'mcp-integration/examples/lib/orchestrator-state-machine.js');

const DEFAULT_TIMEOUT_MS = 120_000;

const log = (msg: string) => console.error(`[orchestrator-tools] ${msg}`);

// 动态加载 lib 模块（ESM 兼容模式：运行时 import() 动态加载，支持加载任意 .js/.cjs 文件）
// - health-monitor.js / orchestrator-state-machine.js 是 CommonJS（module.exports）
// - 在 ESM 下通过 dynamic import() 加载它们，返回值位于 ns.default
async function requireLib(absPath: string): Promise<any> {
  try {
    // 使用 data URL 前缀 + 绝对路径拼接，避开 ESM 对绝对文件 URL 的跨平台差异
    const fileUrl = 'file:///' + absPath.replace(/\\/g, '/').replace(/^\/+/, '');
    const ns = await import(fileUrl);
    return ns && (ns as any).default ? (ns as any).default : ns;
  } catch (e: any) {
    throw new Error(`Failed to load ${absPath}: ${e.message}`);
  }
}

// ============================================================
// 类型定义
// ============================================================

interface SkillResult<T = any> {
  ok: boolean;
  command: string;
  data?: T;
  error?: string;
  warnings?: string[];
  nextActions?: string[];
  duration?: number;
}

interface LLMRequest {
  type: 'llm:request';
  id: number;
  system?: string;
  messages: Array<{ role: string; content: string }>;
  maxTokens?: number;
  temperature?: number;
}

interface LLMResponse {
  type: 'llm:response';
  id: number;
  ok: boolean;
  content?: string;
  model?: string;
  error?: string;
}

// ============================================================
// MCP Sampling：通过 IPC 转发 Skill 的 LLM 请求到 TRAE Client
// ============================================================

/**
 * 延迟检测 Client 是否支持 sampling。
 * 注意：不能在 server.connect() 后立即检测，因为 initialize 握手还未完成。
 * 在实际处理 LLM 请求时动态检测并缓存结果。
 */
let _samplingChecked = false;
let _samplingEnabled = false;

function isSamplingEnabled(): boolean {
  if (!_samplingChecked) {
    try {
      const clientCapabilities = (server as any).getClientCapabilities?.() || {};
      _samplingEnabled = !!clientCapabilities?.sampling;
    } catch {
      _samplingEnabled = false;
    }
    _samplingChecked = true;
    log(`Client sampling support: ${_samplingEnabled ? 'YES' : 'NO'}`);
  }
  return _samplingEnabled;
}

async function handleLLMRequest(
  child: any,
  request: LLMRequest
): Promise<void> {
  const msgId = request.id;
  log(`LLM request #${msgId}: ${request.messages.length} messages, maxTokens=${request.maxTokens}`);

  if (!isSamplingEnabled()) {
    child.send({
      type: 'llm:response',
      id: msgId,
      ok: false,
      error: 'MCP sampling not available (client does not support sampling)',
    } as LLMResponse);
    return;
  }

  try {
    const result = await server.request(
      {
        method: 'sampling/createMessage',
        params: {
          messages: request.messages.map(m => ({
            role: m.role as 'user' | 'assistant',
            content: { type: 'text' as const, text: m.content },
          })),
          systemPrompt: request.system || undefined,
          temperature: request.temperature,
          maxTokens: request.maxTokens || 4096,
        },
      },
      CreateMessageRequestSchema as any,
    );

    const text = (result as any)?.content?.text || '';
    const model = (result as any)?.model || 'unknown';

    child.send({
      type: 'llm:response',
      id: msgId,
      ok: true,
      content: text,
      model,
    } as LLMResponse);

    log(`LLM response #${msgId}: ${text.length} chars from ${model}`);
  } catch (err: any) {
    log(`LLM request #${msgId} FAILED: ${err.message}`);
    child.send({
      type: 'llm:response',
      id: msgId,
      ok: false,
      error: err.message?.slice(0, 500) || 'MCP sampling failed',
    } as LLMResponse);
  }
}

// ============================================================
// 调用 Skill CLI（使用 fork + IPC 替代 exec）
// ============================================================

async function callSkill(
  skill: string,
  command: string,
  input: Record<string, any>,
  options: { timeoutMs?: number; cwd?: string } = {}
): Promise<SkillResult> {
  const startTime = Date.now();
  const timeout = options.timeoutMs ?? DEFAULT_TIMEOUT_MS;
  const cwd = options.cwd ?? PROJECT_ROOT;

  if (!existsSync(SKILL_CLI_BIN)) {
    return {
      ok: false,
      command: `${skill}.${command}`,
      error: `Skill CLI not found at ${SKILL_CLI_BIN}. ` +
        `Build it first: cd ${SKILL_BUNDLE_PATH} && pnpm build`,
    };
  }

  // 通过 stdin 传递 input JSON（避免命令行长度限制 + PowerShell 解析问题）
  const inputJson = JSON.stringify(input);
  const args = [skill, command, '--project-root', cwd];

  return new Promise((resolvePromise) => {
    let stdout = '';
    let stderr = '';
    let resolved = false;

    const child = fork(SKILL_CLI_BIN, args, {
      cwd: PROJECT_ROOT,
      stdio: ['pipe', 'pipe', 'pipe', 'ipc'],
      env: {
        ...process.env,
        // 始终开启 MCP sampling 尝试（子进程会自动检测，失败则降级）
        MCP_SAMPLING_ENABLED: '1',
        // 告诉 skill-cli 从 stdin 读取 input（避免命令行长度限制 + PowerShell 解析问题）
        SKILL_INPUT_FROM_STDIN: '1',
      },
    });

    // 将 input JSON 写入子进程 stdin
    child.stdin?.write(inputJson);
    child.stdin?.end();

    // 收集 stdout / stderr
    child.stdout?.on('data', (data: Buffer) => { stdout += data.toString(); });
    child.stderr?.on('data', (data: Buffer) => { stderr += data.toString(); });

    // 处理来自子进程的 IPC 消息（LLM 请求）
    child.on('message', (msg: any) => {
      if (msg?.type === 'llm:request') {
        handleLLMRequest(child, msg as LLMRequest).catch((err) => {
          log(`LLM handler error: ${err.message}`);
        });
      }
    });

    // 超时处理
    const timer = setTimeout(() => {
      if (!resolved) {
        child.kill('SIGTERM');
        setTimeout(() => {
          if (!resolved) child.kill('SIGKILL');
        }, 5000);
        resolvePromise({
          ok: false,
          command: `${skill}.${command}`,
          error: `Timeout after ${timeout}ms`,
          duration: Date.now() - startTime,
        });
        resolved = true;
      }
    }, timeout);

    // 子进程退出
    child.on('close', (code: number) => {
      clearTimeout(timer);
      if (resolved) return;

      if (stderr) {
        log(`[${skill}.${command}] stderr: ${stderr.slice(0, 500)}`);
      }

      try {
        const result: SkillResult = JSON.parse(stdout);
        result.duration = Date.now() - startTime;
        resolvePromise(result);
      } catch {
        // stdout 不是 JSON
        resolvePromise({
          ok: false,
          command: `${skill}.${command}`,
          error: code !== 0
            ? `Process exited with code ${code}. stdout: ${stdout.slice(0, 200)}`
            : `Failed to parse output: ${stdout.slice(0, 200)}`,
          duration: Date.now() - startTime,
        });
      }
      resolved = true;
    });

    // 子进程错误
    child.on('error', (err: Error) => {
      clearTimeout(timer);
      if (resolved) return;
      log(`[${skill}.${command}] fork error: ${err.message}`);
      resolvePromise({
        ok: false,
        command: `${skill}.${command}`,
        error: err.message,
        duration: Date.now() - startTime,
      });
      resolved = true;
    });
  });
}

